algorithms.pseudocode:
EnumerateCircuits(edges, max_size):
  by_size[1] = {Const(F), Const(T)} ∪ {Var(e) : e ∈ edges}
  for s = 3 to max_size:
    for a,b with 1+a+b = s:
      for c1 ∈ by_size[a], c2 ∈ by_size[b]:
        by_size[s] += {AND(c1,c2), OR(c1,c2)}
  return ⋃ by_size

GreedySandwich(f, circuits, graphs):
  Compute disagreement table D[i,G]
  unhit = non-computing circuits
  while unhit ≠ ∅:
    G* = argmax_G |{i ∈ unhit : D[i,G]}|
    witnesses += {G*}
    unhit -= {i : D[i,G*]}
  return partition(witnesses, f)
